    {
      "card_ids": ["C53"],
      "claim": "Paliperidone ER absolute bioavailability was 28% in healthy volunteers vs IV, supporting F >=20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Pentazocine mean absolute bioavailability was 18% in healthy subjects after 100 mg tablets vs IV, arguing for F <20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transfer evidence molecules have absolute or systemic oral bioavailability at or above 20% (28-71%), supporting a high prediction. Two high-transfer molecules (pentazocine, meptazinol) are below 20%, creating moderate uncertainty.",
  "evidence_gaps": [
    "Conflicting low-F evidence from high-transfer molecules 1 and 5; their healthy-subject absolute values are below 20%.",
    "Some records are from cirrhosis patients or altered formulations, limiting directness to ordinary healthy-subject oral bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

